-- Identity-only boss variety. Never updates user_patrols or battle_replay_sessions.
-- Preserve every combat field; only characterId/name/rarity follow the selected character.
create temporary table quest_roster_before on commit drop as
select * from public.canonical_quest_master where version='2026-08-30' and is_production_enabled;
do $patch$
declare mapping jsonb; q public.canonical_quest_master%rowtype; ids jsonb; members jsonb;
begin
for mapping in select value from jsonb_array_elements($map$[{"quest_id":"q_shinjuku_1","old_ids":["char_mio_01","char_takuro_01","char_leon_01","char_jihoon_01","char_kageyama_01"],"new_ids":["char_shin_01","char_tomoya_01","char_serika_01","char_jihoon_01","char_makoto_01"]},{"quest_id":"q_shinjuku_2","old_ids":["char_mio_01","char_takuro_01","char_leon_01","char_jihoon_01","char_kageyama_01"],"new_ids":["char_kageyama_01","char_takuro_01","char_leon_01","char_seiya_01","char_taiga_01"]},{"quest_id":"q_shinjuku_3","old_ids":["char_mio_01","char_takuro_01","char_leon_01","char_jihoon_01","char_kageyama_01"],"new_ids":["char_mio_01","char_go_01","char_kengo_01","char_miyabi_01","char_kaede_01"]},{"quest_id":"q_shibuya_1","old_ids":["char_ageha_01","char_leo_01","char_sora_01","char_noa_01","char_minami_01"],"new_ids":["char_yukina_01","char_ren_male_01","char_kaito_01","char_minami_01","char_naoto_01"]},{"quest_id":"q_shibuya_2","old_ids":["char_ageha_01","char_leo_01","char_sora_01","char_noa_01","char_minami_01"],"new_ids":["char_reina_01","char_noa_01","char_martina_01","char_yuki_01","char_momoko_01"]},{"quest_id":"q_shibuya_3","old_ids":["char_ageha_01","char_leo_01","char_sora_01","char_noa_01","char_minami_01"],"new_ids":["char_ageha_01","char_leo_01","char_reiji_01","char_cecile_01","char_koharu_01"]},{"quest_id":"q_ikebukuro_1","old_ids":["char_koharu_01","char_takeshi_01","char_shun_01","char_kenji_01","char_momoko_01"],"new_ids":["char_momoko_01","char_kenji_01","char_shun_01","char_naoto_01","char_yuki_01"]},{"quest_id":"q_ikebukuro_2","old_ids":["char_koharu_01","char_takeshi_01","char_shun_01","char_kenji_01","char_momoko_01"],"new_ids":["char_takeshi_01","char_daimon_01","char_ren_male_01","char_minami_01","char_noa_01"]},{"quest_id":"q_ikebukuro_3","old_ids":["char_koharu_01","char_takeshi_01","char_shun_01","char_kenji_01","char_momoko_01"],"new_ids":["char_koharu_01","char_leo_01","char_lucas_01","char_riki_01","char_cecile_01"]},{"quest_id":"q_roppongi_1","old_ids":["char_kaede_01","char_maya_01","char_seiya_01","char_taiga_01","char_cecile_01"],"new_ids":["char_rin_01","char_tatsuya_01","char_makoto_01","char_shion_01","char_yuki_01"]},{"quest_id":"q_roppongi_2","old_ids":["char_kaede_01","char_maya_01","char_seiya_01","char_taiga_01","char_cecile_01"],"new_ids":["char_seiya_01","char_maya_01","char_taiga_01","char_kageyama_01","char_cecile_01"]},{"quest_id":"q_roppongi_3","old_ids":["char_kaede_01","char_maya_01","char_seiya_01","char_taiga_01","char_cecile_01"],"new_ids":["char_kaede_01","char_kengo_01","char_mio_01","char_miyabi_01","char_leo_01"]},{"quest_id":"q_akihabara_1","old_ids":["char_karen_01","char_miyabi_01","char_alice_01","char_mei_01","char_aoi_01"],"new_ids":["char_masato_01","char_souta_01","char_yoshihiko_01","char_ren_01","char_mei_01"]},{"quest_id":"q_akihabara_2","old_ids":["char_karen_01","char_miyabi_01","char_alice_01","char_mei_01","char_aoi_01"],"new_ids":["char_alice_01","char_shion_01","char_rui_01","char_aoi_01","char_yukina_01"]},{"quest_id":"q_akihabara_3","old_ids":["char_karen_01","char_miyabi_01","char_alice_01","char_mei_01","char_aoi_01"],"new_ids":["char_karen_01","char_miyabi_01","char_reiji_01","char_ageha_01","char_martina_01"]},{"quest_id":"q_kawasaki_1","old_ids":["char_go_01","char_kengo_01","char_lucas_01","char_tetsu_01","char_riki_01"],"new_ids":["char_gou_01","char_joe_01","char_daimon_01","char_mark_01","char_naoto_01"]},{"quest_id":"q_kawasaki_2","old_ids":["char_go_01","char_kengo_01","char_lucas_01","char_tetsu_01","char_riki_01"],"new_ids":["char_tetsu_01","char_takuro_01","char_lucas_01","char_leon_01","char_riki_01"]},{"quest_id":"q_kawasaki_3","old_ids":["char_go_01","char_kengo_01","char_lucas_01","char_tetsu_01","char_riki_01"],"new_ids":["char_go_01","char_kengo_01","char_leo_01","char_maya_01","char_koharu_01"]},{"quest_id":"q_yokohama_1","old_ids":["char_genji_01","char_long_01","char_sakura_01","char_yuji_01","char_riki_01"],"new_ids":["char_sawat_01","char_shin_01","char_yuji_01","char_serika_01","char_yuki_01"]},{"quest_id":"q_yokohama_2","old_ids":["char_genji_01","char_long_01","char_sakura_01","char_yuji_01","char_riki_01"],"new_ids":["char_genji_01","char_long_01","char_sakura_01","char_mark_01","char_riki_01"]},{"quest_id":"q_yokohama_3","old_ids":["char_genji_01","char_long_01","char_sakura_01","char_yuji_01","char_riki_01"],"new_ids":["char_mio_01","char_kaede_01","char_go_01","char_kengo_01","char_leo_01"]}]$map$::jsonb)
loop
select * into strict q from public.canonical_quest_master where version='2026-08-30' and quest_id=mapping->>'quest_id' for update;
select jsonb_agg(m->>'characterId' order by ord) into ids from jsonb_array_elements(q.progression_boss_members) with ordinality e(m,ord);
if ids=mapping->'new_ids' then continue;end if;
if ids is distinct from mapping->'old_ids' then raise exception 'Unexpected current roster: %',q.quest_id;end if;
if exists(select 1 from jsonb_array_elements(q.progression_boss_members) with ordinality e(m,ord)
left join public.canonical_character_master c on c.version='2026-08-21' and c.character_id=mapping->'new_ids'->>(ord::int-1)
where c.character_id is null or c.attribute is distinct from m->>'alignment') then raise exception 'Invalid character or changed alignment';end if;
select jsonb_agg(m||jsonb_build_object('characterId',c.character_id,'name',c.display_name,'rarity',c.rarity) order by ord)
into members from jsonb_array_elements(q.progression_boss_members) with ordinality e(m,ord)
join public.canonical_character_master c on c.version='2026-08-21' and c.character_id=mapping->'new_ids'->>(ord::int-1);
update public.canonical_quest_master set progression_boss_members=members where version=q.version and quest_id=q.quest_id;
end loop;
end $patch$;
do $verify$
begin
if (select count(*) from quest_roster_before)<>21 then raise exception 'Expected 21 stages';end if;
if exists(select 1 from quest_roster_before b join public.canonical_quest_master q using(version,quest_id)
where (to_jsonb(b)-'progression_boss_members') is distinct from (to_jsonb(q)-'progression_boss_members')) then raise exception 'Non-roster master changed';end if;
if exists(select 1 from quest_roster_before b join public.canonical_quest_master q using(version,quest_id)
cross join lateral jsonb_array_elements(b.progression_boss_members) with ordinality e(m,n)
where (m-'characterId'-'name'-'rarity') is distinct from ((q.progression_boss_members->(n::int-1))-'characterId'-'name'-'rarity')) then raise exception 'Combat fields changed';end if;
if exists(select 1 from public.canonical_quest_master q cross join lateral jsonb_array_elements(q.progression_boss_members) e(m)
where version='2026-08-30' and is_production_enabled group by town_id having count(*)<>15 or count(distinct m->>'characterId')<>15) then raise exception 'Town roster not unique';end if;
if exists(select 1 from public.canonical_quest_master q where version='2026-08-30' and is_production_enabled and jsonb_array_length(public.quest_progression_enemy_snapshot_v1(null,q.quest_id)->'members')<>5) then raise exception 'Runtime snapshot invalid';end if;
end $verify$;
